Definition bp_ms (pc : Z) (rax : word) (spa : Z) (gp tp t0 t1 t2 sp0 a0 a1 a2 a3 a4 a5 a6 a7 : word) (E P ff p1 n : Z)
    (t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state :=
  MS (mkR rax (wz spa) gp tp t0 t1 t2 sp0 (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
          (shw (E + 16)) (wz E) (wz p1) (wz P) (wz (P + 72)) (wz (E + 16)) (wz BP_JT) (wz n) (shw ff) (shw (P + 72)) t3 t4 t5 t6)
     F (wz pc) fc None m (seg_rom bsegs).

