Lemma ro_cells_reshape : forall segs m A cs cs',
  ro_cells segs m A cs -> cells_wf cs' -> cells_bytes cs' = cells_bytes cs -> ro_cells segs m A cs'.
Proof. intros segs m A cs cs' [WF B] WF' E. split; [exact WF'| rewrite E; exact B]. Qed.

(* [comment removed for export] *)
Lemma bp_jt : forall m, mem_inv bsegs m -> ro_cells bsegs m BP_JT BP_JT_CELLS.
Proof.
  intros m MI.
  apply (ro_cells_reshape bsegs m BP_JT [CB (length (cells_bytes BP_JT_CELLS)) (cells_bytes BP_JT_CELLS)] BP_JT_CELLS).
  - apply (ro_cells_image bsegs m); [exact MI | vm_compute; reflexivity | unfold BP_JT; lia | vm_compute; intro Hc; discriminate Hc].
  - vm_compute; tauto.
  - vm_compute; reflexivity.
Qed.
