  stk bsegs m lo (bv_unsigned sp) -> lo + 304 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp mod 16 = 0 -> mem_inv bsegs m ->
  (forall (m1 : mem) (spa : Z) (j184 : list byte) (gap : list cell),
