Definition bp_frontW (lo spa ff fp E : Z) : list (Z * Z) :=
  [(lo, spa + 184); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16); (E, E + 24)]%Z.
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma bp_front : forall (Q : machine_state -> Prop) (m1 : mem) (sp : word) (spa lo shi : Z) (LF : list fframe) (LB : list block) (s : as_St H) (m0 : mem)
    (P E p0 n : Z) (c : pcore) (pad7 pad2 ej j184 : list byte) (gap : list cell)
    (ra gp tp t0 t1 t2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  (* [comment removed for export] *)
  rw_cells bsegs m1 spa [CB 184 j184] -> rw_cells bsegs m1 (spa + 184) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184) ->
  (spa = bv_unsigned sp + -288 \/ spa = bv_unsigned sp + -304) -> spa mod 32 = 0 ->
  stk bsegs m1 lo spa -> lo + 304 + AINTRIN_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp <= shi -> mem_inv bsegs m1 ->
